// Standalone preview only. Real webviews receive --vscode-* values from the host.
const themePreview=document.createElement('select');themePreview.id='preview-theme';themePreview.setAttribute('aria-label','Preview theme');themePreview.innerHTML='<option value="dark">Dark Modern</option><option value="light">Light Modern</option><option value="contrast">High Contrast</option>';document.querySelector('.preview-controls').prepend(themePreview);themePreview.value=sessionStorage.getItem('uspec-preview-theme')||'dark';document.body.dataset.previewTheme=themePreview.value;themePreview.onchange=()=>{document.body.dataset.previewTheme=themePreview.value;sessionStorage.setItem('uspec-preview-theme',themePreview.value);};
